import { useEffect, useState } from "react";
import axios from "axios";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = "http://localhost:5000";

function AdminAnonymousResults({ theme }) {
  const [candidates, setCandidates] = useState([]);

  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch (err) {
      console.error("Failed to fetch candidates", err);
    }
  };

  useEffect(() => {
    fetchCandidates();

    const interval = setInterval(() => {
      fetchCandidates();
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const key = candidate.candidacy || "Other";
    if (!acc[key]) acc[key] = [];
    acc[key].push(candidate);
    return acc;
  }, {});

  return (
    <div style={{ padding: 20 }}>
      <h2>📊 Anonymous Election Monitor</h2>

      {Object.entries(groupedCandidates).map(([position, list]) => {
        const sorted = [...list].sort(
          (a, b) => (b.votes || 0) - (a.votes || 0)
        );

        const data = {
          labels: sorted.map((_, index) => `Candidate ${index + 1}`),
          datasets: [
            {
              label: `${position} Votes`,
              data: sorted.map((c) => c.votes || 0),
              backgroundColor: theme.button,
            },
          ],
        };

        return (
          <div
            key={position}
            style={{
              marginBottom: 40,
              backgroundColor: theme.card,
              padding: 20,
              borderRadius: 8,
            }}
          >
            <h3>{position}</h3>
            <Bar data={data} />
          </div>
        );
      })}
    </div>
  );
}

export default AdminAnonymousResults;
